202	  public List<ExtendedBlockId> getExtendedBlockId(Path filePath, long fileLen)
203	      throws IOException {
204	    List<ExtendedBlockId> keys = new ArrayList<>();
205	    HdfsBlockLocation[] locs = (HdfsBlockLocation[]) fs.getFileBlockLocations(
206	        filePath, 0, fileLen);
207	    for (HdfsBlockLocation loc : locs) {
208	      long bkid = loc.getLocatedBlock().getBlock().getBlockId();
209	      String bpid = loc.getLocatedBlock().getBlock().getBlockPoolId();
210	      keys.add(new ExtendedBlockId(bkid, bpid));
211	    }
212	    return keys;
213	  }
