215	  @Test(timeout = 60000)
216	  public void testCacheRecovery() throws Exception {
217	    final int cacheBlocksNum =
218	        Ints.checkedCast(CACHE_AMOUNT / BLOCK_SIZE);
219	    BlockReaderTestUtil.enableHdfsCachingTracing();
220	    Assert.assertEquals(0, CACHE_AMOUNT % BLOCK_SIZE);
221	
222	    final Path testFile = new Path("/testFile");
223	    final long testFileLen = cacheBlocksNum * BLOCK_SIZE;
224	    DFSTestUtil.createFile(fs, testFile,
225	        testFileLen, (short) 1, 0xbeef);
226	    List<ExtendedBlockId> blockKeys =
227	        getExtendedBlockId(testFile, testFileLen);
228	    fs.addCachePool(new CachePoolInfo("testPool"));
229	    final long cacheDirectiveId = fs.addCacheDirective(
230	        new CacheDirectiveInfo.Builder().setPool("testPool").
231	            setPath(testFile).setReplication((short) 1).build());
232	    // wait for caching
233	    GenericTestUtils.waitFor(new Supplier<Boolean>() {
234	      @Override
235	      public Boolean get() {
236	        MetricsRecordBuilder dnMetrics = getMetrics(dn.getMetrics().name());
237	        long blocksCached =
238	            MetricsAsserts.getLongCounter("BlocksCached", dnMetrics);
239	        if (blocksCached != cacheBlocksNum) {
240	          LOG.info("waiting for " + cacheBlocksNum + " blocks to " +
241	              "be cached. Right now " + blocksCached + " blocks are cached.");
242	          return false;
243	        }
244	        LOG.info(cacheBlocksNum + " blocks are now cached.");
245	        return true;
246	      }
247	    }, 1000, 30000);
248	
249	    assertEquals(CACHE_AMOUNT, cacheManager.getCacheUsed());
250	    Map<ExtendedBlockId, Byte> blockKeyToVolume =
251	        PmemVolumeManager.getInstance().getBlockKeyToVolume();
252	    // All block keys should be kept in blockKeyToVolume
253	    assertEquals(blockKeyToVolume.size(), cacheBlocksNum);
254	    assertTrue(blockKeyToVolume.keySet().containsAll(blockKeys));
255	    // Test each replica's cache file path
256	    for (ExtendedBlockId key : blockKeys) {
257	      if (blockPoolId.isEmpty()) {
258	        blockPoolId = key.getBlockPoolId();
259	      }
260	      String cachePath = cacheManager.
261	          getReplicaCachePath(key.getBlockPoolId(), key.getBlockId());
262	      // The cachePath shouldn't be null if the replica has been cached
263	      // to pmem.
264	      assertNotNull(cachePath);
265	      Path path = new Path(cachePath);
266	      String fileName = path.getName();
267	      if (cachePath.startsWith(PMEM_DIR_0)) {
268	        String expectPath = PmemVolumeManager.
269	            getRealPmemDir(PMEM_DIR_0) + "/" + key.getBlockPoolId();
270	        assertTrue(path.toString().startsWith(expectPath));
271	        assertTrue(key.getBlockId() == Long.parseLong(fileName));
272	      } else if (cachePath.startsWith(PMEM_DIR_1)) {
273	        String expectPath = PmemVolumeManager.
274	            getRealPmemDir(PMEM_DIR_1) + "/" + key.getBlockPoolId();
275	        assertTrue(path.toString().startsWith(expectPath));
276	        assertTrue(key.getBlockId() == Long.parseLong(fileName));
277	      } else {
278	        fail("The cache path is not the expected one: " + cachePath);
279	      }
280	    }
281	
282	    // Trigger cache recovery
283	    shutdownCluster();
284	    restartCluster();
285	
286	    assertEquals(CACHE_AMOUNT, cacheManager.getCacheUsed());
287	    blockKeyToVolume = PmemVolumeManager.getInstance().getBlockKeyToVolume();
288	    // All block keys should be kept in blockKeyToVolume
289	    assertEquals(blockKeyToVolume.size(), cacheBlocksNum);
290	    assertTrue(blockKeyToVolume.keySet().containsAll(blockKeys));
291	    // Test each replica's cache file path
292	    for (ExtendedBlockId key : blockKeys) {
293	      String cachePath = cacheManager.
294	          getReplicaCachePath(key.getBlockPoolId(), key.getBlockId());
295	      // The cachePath shouldn't be null if the replica has been cached
296	      // to pmem.
297	      assertNotNull(cachePath);
298	      Path path = new Path(cachePath);
299	      String fileName = path.getName();
300	      if (cachePath.startsWith(PMEM_DIR_0)) {
301	        String expectPath = PmemVolumeManager.
302	            getRealPmemDir(PMEM_DIR_0) + "/" + key.getBlockPoolId();
303	        assertTrue(path.toString().startsWith(expectPath));
304	        assertTrue(key.getBlockId() == Long.parseLong(fileName));
305	      } else if (cachePath.startsWith(PMEM_DIR_1)) {
306	        String expectPath = PmemVolumeManager.
307	            getRealPmemDir(PMEM_DIR_1) + "/" + key.getBlockPoolId();
308	        assertTrue(path.toString().startsWith(expectPath));
309	        assertTrue(key.getBlockId() == Long.parseLong(fileName));
310	      } else {
311	        fail("The cache path is not the expected one: " + cachePath);
312	      }
313	    }
314	
315	    // Uncache the test file
316	    for (ExtendedBlockId key : blockKeys) {
317	      cacheManager.uncacheBlock(blockPoolId, key.getBlockId());
318	    }
319	    // Wait for uncaching
320	    GenericTestUtils.waitFor(new Supplier<Boolean>() {
321	      @Override
322	      public Boolean get() {
323	        MetricsRecordBuilder dnMetrics = getMetrics(dn.getMetrics().name());
324	        long blocksUncached =
325	            MetricsAsserts.getLongCounter("BlocksUncached", dnMetrics);
326	        if (blocksUncached != cacheBlocksNum) {
327	          LOG.info("waiting for " + cacheBlocksNum + " blocks to be " +
328	              "uncached. Right now " + blocksUncached +
329	              " blocks are uncached.");
330	          return false;
331	        }
332	        LOG.info(cacheBlocksNum + " blocks have been uncached.");
333	        return true;
334	      }
335	    }, 1000, 30000);
336	
337	    // It is expected that no pmem cache space is used.
338	    assertEquals(0, cacheManager.getCacheUsed());
339	    // No record should be kept by blockKeyToVolume after testFile is uncached.
340	    assertEquals(blockKeyToVolume.size(), 0);
341	  }
